use super::*;

pub(crate) fn row_to_lesson(r: &rusqlite::Row) -> rusqlite::Result<Lesson> {
    Ok(Lesson {
        id: r.get(0)?,
        mistake: r.get(1)?,
        cause: r.get(2)?,
        rule: r.get(3)?,
        provenance: r.get(4)?,
        status: r.get(5)?,
        seen: r.get(6)?,
        created_at: r.get(7)?,
        updated_at: r.get(8)?,
    })
}
